/* ===================== BÀI 1 · Bit, byte, nhị phân và hex ===================== */
/* Bài 1 · Bit, byte, nhị phân và hex (FND-001) — sinh bởi tools/author/nentang/m01.py, không sửa tay.
   Bảng bit tương tác, phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeNtBits(document.getElementById("bits-l1"),{"id": "l1", "v": 165});
makeMtLab(document.getElementById("lab-l1"),{id:"l1",scenarios:[{"label": "Ví dụ: Đọc byte 0A5H theo từng bit", "note": "Cộng trọng số của các bit bằng 1, kiểm tra bằng 16 × nibble cao + nibble thấp.", "steps": [{"t": "Byte 0A5H viết ra 8 bit", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div>", "say": "<p>Đổi từng chữ số hex thành 4 bit: A = 1010, 5 = 0101. Viết theo thứ tự bit 7 … bit 0, bit 7 ở bên trái.<\/p>"}, {"t": "Nibble cao A = 1010, nibble thấp 5 = 0101", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td class=\"new\">128<\/td><td class=\"new\">64<\/td><td class=\"new\">32<\/td><td class=\"new\">16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td class=\"new\">1<\/td><td class=\"new\">0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table><\/div>", "say": "<p>Bốn bit 7…4 là nibble cao, bốn bit 3…0 là nibble thấp.<\/p>"}, {"t": "Bit 7 = 1: cộng 128, tổng 128", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td class=\"new\">128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"new\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">128 = <b>128<\/b><\/p>"}, {"t": "Bit 5 = 1: cộng 32, tổng 160", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td class=\"new\">32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"new\">1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">128 + 32 = <b>160<\/b><\/p>"}, {"t": "Bit 2 = 1: cộng 4, tổng 164", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td class=\"new\">4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td class=\"new\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">128 + 32 + 4 = <b>164<\/b><\/p>", "ask": {"q": "Đã cộng 128 + 32 = 160. Bit tiếp theo bằng 1 là bit nào?", "o": ["Bit 4 (trọng số 16)", "Bit 2 (trọng số 4)", "Bit 1 (trọng số 2)"], "a": 1}}, {"t": "Bit 0 = 1: cộng 1, tổng 165", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td class=\"new\">1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">128 + 32 + 4 + 1 = <b>165<\/b><\/p>"}, {"t": "0A5H = 165, kiểm tra bằng 16 × 10 + 5", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">128 + 32 + 4 + 1 = 165 · 16 × 10 + 5 = <b>165<\/b> ✓<\/p>", "say": "<p>Hai cách tính cho cùng kết quả. Nên kiểm tra chéo như vậy mỗi khi đổi hệ.<\/p>"}]}, {"label": "Ví dụ: Đổi 200 sang hex và nhị phân", "note": "Chia cho 16: thương là nibble cao, số dư là nibble thấp.", "steps": [{"t": "Chia 200 cho 16", "html": "<p class=\"mt-calc\">200 = 12 × 16 + 8<\/p>", "say": "<p>Với số 0…255, thương của phép chia cho 16 là nibble cao, số dư là nibble thấp.<\/p>"}, {"t": "Nibble cao C, nibble thấp 8: 0C8H", "html": "<p class=\"mt-calc\">12 → C · 8 → 8 · viết trong A51: <b>0C8H<\/b><\/p>", "ask": {"q": "Thương 12 viết thành chữ số hex nào?", "o": ["B", "12", "C"], "a": 2}, "say": "<p>Chữ số đầu là C (chữ cái) nên trong A51 / MASM phải viết thêm số 0 đứng đầu: 0C8H.<\/p>"}, {"t": "Thay mỗi chữ số hex bằng 4 bit: 1100 1000B", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">C = 1100 · 8 = 1000 → <b>1100 1000B<\/b><\/p>"}, {"t": "Kiểm tra: 128 + 64 + 8 = 200", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"hi\">1<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">128 + 64 + 8 = <b>200<\/b> ✓<\/p>"}]}, {"label": "Ví dụ: MOV P\u0031,#0A5H và 8 LED", "note": "Bit k của P\u0031 điều khiển chân P\u0031.k; LED giả định sáng khi chân ở mức 0.", "steps": [{"t": "Sau reset: P\u0031 = FFH, mọi chân ở mức 1", "html": "<div class=\"nt-leds\" role=\"img\" aria-label=\"8 LED trên P\u0031: P\u0031.7 tắt, P\u0031.6 tắt, P\u0031.5 tắt, P\u0031.4 tắt, P\u0031.3 tắt, P\u0031.2 tắt, P\u0031.1 tắt, P\u0031.0 tắt\"><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.7<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.6<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.5<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.4<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.3<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.2<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.1<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.0<\/b><span>1 (cao)<\/span><\/div><\/div><p class=\"mt-calc\">P\u0031 = 0FFH = 1111 1111B<\/p>", "say": "<p>Sau reset, bộ chốt của các cổng 8051 có giá trị FFH. Với LED nối theo giả định của bài (sáng khi chân ở mức 0), cả 8 LED đều tắt.<\/p>"}, {"t": "Lệnh MOV P\u0031,#0A5H là 3 byte", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>75H<\/td><td>opcode: ghi hằng vào ô trực tiếp<\/td><\/tr><tr><td>0001H<\/td><td class=\"new\">90H<\/td><td>địa chỉ của P\u0031 (SFR)<\/td><\/tr><tr><td>0002H<\/td><td class=\"new\">A5H<\/td><td>hằng số 0A5H<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mất 2 chu kỳ máy. 90H là địa chỉ của thanh ghi cổng P\u0031 trong vùng SFR.<\/p>"}, {"t": "P\u0031 = 1010 0101B", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Tên<\/td><td>P\u0031.7<\/td><td>P\u0031.6<\/td><td>P\u0031.5<\/td><td>P\u0031.4<\/td><td>P\u0031.3<\/td><td>P\u0031.2<\/td><td>P\u0031.1<\/td><td>P\u0031.0<\/td><\/tr><tr><td>Giá trị<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><\/tbody><\/table><\/div>", "ask": {"q": "Sau lệnh này, LED ở P\u0031.7 sáng hay tắt?", "o": ["Sáng: bit 7 = 1", "Tắt: bit 7 = 1, chân ở mức cao"], "a": 1}}, {"t": "4 LED sáng: P\u0031.6, P\u0031.4, P\u0031.3, P\u0031.1", "html": "<div class=\"nt-leds\" role=\"img\" aria-label=\"8 LED trên P\u0031: P\u0031.7 tắt, P\u0031.6 sáng, P\u0031.5 tắt, P\u0031.4 sáng, P\u0031.3 sáng, P\u0031.2 tắt, P\u0031.1 sáng, P\u0031.0 tắt\"><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.7<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.6<\/b><span>0 (thấp)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.5<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.4<\/b><span>0 (thấp)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.3<\/b><span>0 (thấp)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.2<\/b><span>1 (cao)<\/span><\/div><div class=\"nt-led on\"><i aria-hidden=\"true\"><\/i><b>P\u0031.1<\/b><span>0 (thấp)<\/span><\/div><div class=\"nt-led\"><i aria-hidden=\"true\"><\/i><b>P\u0031.0<\/b><span>1 (cao)<\/span><\/div><\/div>", "say": "<p>LED sáng ở các chân có bit 0. Nếu LED nối theo kiểu khác (sáng khi chân ở mức 1) thì mẫu sáng đảo lại: luôn đọc sơ đồ mạch trước khi đoán.<\/p>"}]}, {"label": "Ví dụ: PSW = 18H chọn băng thanh ghi 3", "note": "Đọc hai bit RS1 (bit 4) và RS0 (bit 3).", "steps": [{"t": "MOV PSW,#18H là 3 byte 75H D0H 18H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>75H<\/td><td>opcode<\/td><\/tr><tr><td>0001H<\/td><td class=\"new\">D0H<\/td><td>địa chỉ của PSW (SFR)<\/td><\/tr><tr><td>0002H<\/td><td>18H<\/td><td>hằng số 18H<\/td><\/tr><\/tbody><\/table>", "say": "<p>Cùng opcode 75H như lệnh ghi P\u0031, chỉ khác byte địa chỉ: D0H là PSW.<\/p>"}, {"t": "18H = 0001 1000B: RS1 = 1, RS0 = 1", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Tên<\/td><td>CY<\/td><td>AC<\/td><td>F0<\/td><td class=\"new\">RS1<\/td><td class=\"new\">RS0<\/td><td>OV<\/td><td>—<\/td><td>P<\/td><\/tr><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td class=\"new\">16<\/td><td class=\"new\">8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td class=\"new\">1<\/td><td class=\"new\">1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div>", "say": "<p>RS1 là bit 4, RS0 là bit 3. Bit 1 không dùng trong bài này; bit P do phần cứng cập nhật theo thanh ghi A.<\/p>"}, {"t": "Số băng = 2 × RS1 + RS0 = 3", "html": "<p class=\"mt-calc\">RS1 RS0 = 11B = <b>3<\/b><\/p>", "ask": {"q": "Băng thanh ghi 3 bắt đầu ở ô RAM trong nào?", "o": ["03H", "18H", "30H"], "a": 1}}, {"t": "Băng 3: R0…R7 ở ô 18H…1FH", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Băng<\/th><th scope=\"col\">RS1 RS0<\/th><th scope=\"col\">Ô RAM của R0…R7<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>0 0<\/td><td>00H–07H<\/td><\/tr><tr><td>1<\/td><td>0 1<\/td><td>08H–0FH<\/td><\/tr><tr><td>2<\/td><td>1 0<\/td><td>10H–17H<\/td><\/tr><tr><td class=\"new\">3<\/td><td class=\"new\">1 1<\/td><td class=\"new\">18H–1FH<\/td><\/tr><\/tbody><\/table>", "say": "<p>Băng n bắt đầu ở ô 8 × n. Ghi cả byte PSW cũng ghi CY, AC, F0, OV về 0; riêng bit P luôn do phần cứng tính lại theo thanh ghi A. Cách chỉ đổi 2 bit RS1, RS0 học ở Bài 3.<\/p>"}]}, {"label": "Ví dụ: Byte mã máy và chu kỳ của 3 lệnh", "note": "Đếm byte, đếm chu kỳ máy, xem thứ tự byte của hằng 16 bit.", "steps": [{"t": "Đoạn 3 lệnh bắt đầu ở địa chỉ 0000H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Lệnh A51<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>74 3C<\/td><td>MOV A,#3CH<\/td><td>1<\/td><\/tr><tr><td>0002H<\/td><td>75 90 A5<\/td><td>MOV P\u0031,#0A5H<\/td><td>2<\/td><\/tr><tr><td>0005H<\/td><td>90 12 34<\/td><td>MOV DPTR,#1234H<\/td><td>2<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mỗi lệnh chiếm 2 hoặc 3 byte liên tiếp. Byte đầu là opcode; các byte sau là hằng số hoặc địa chỉ.<\/p>"}, {"t": "MOV A,#3CH: 2 byte, 1 chu kỳ máy", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Lệnh A51<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td class=\"new\">0000H<\/td><td class=\"new\">74 3C<\/td><td class=\"new\">MOV A,#3CH<\/td><td class=\"new\">1<\/td><\/tr><tr><td>0002H<\/td><td>75 90 A5<\/td><td>MOV P\u0031,#0A5H<\/td><td>2<\/td><\/tr><tr><td>0005H<\/td><td>90 12 34<\/td><td>MOV DPTR,#1234H<\/td><td>2<\/td><\/tr><\/tbody><\/table>"}, {"t": "MOV P\u0031,#0A5H: 3 byte, 2 chu kỳ máy", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Lệnh A51<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>74 3C<\/td><td>MOV A,#3CH<\/td><td>1<\/td><\/tr><tr><td class=\"new\">0002H<\/td><td class=\"new\">75 90 A5<\/td><td class=\"new\">MOV P\u0031,#0A5H<\/td><td class=\"new\">2<\/td><\/tr><tr><td>0005H<\/td><td>90 12 34<\/td><td>MOV DPTR,#1234H<\/td><td>2<\/td><\/tr><\/tbody><\/table>"}, {"t": "MOV DPTR,#1234H: 3 byte, 2 chu kỳ máy", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Lệnh A51<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>74 3C<\/td><td>MOV A,#3CH<\/td><td>1<\/td><\/tr><tr><td>0002H<\/td><td>75 90 A5<\/td><td>MOV P\u0031,#0A5H<\/td><td>2<\/td><\/tr><tr><td class=\"new\">0005H<\/td><td class=\"new\">90 12 34<\/td><td class=\"new\">MOV DPTR,#1234H<\/td><td class=\"new\">2<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "MOV DPTR,#1234H dịch thành 90H và hai byte nào, theo thứ tự?", "o": ["34H rồi 12H", "12H rồi 34H"], "a": 1}, "say": "<p>Với lệnh này, 8051 đặt byte cao (12H) trước byte thấp (34H).<\/p>"}, {"t": "Tổng: 8 byte, 5 chu kỳ máy = 5 µs ở 12 MHz", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Lệnh A51<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>74 3C<\/td><td>MOV A,#3CH<\/td><td>1<\/td><\/tr><tr><td>0002H<\/td><td>75 90 A5<\/td><td>MOV P\u0031,#0A5H<\/td><td>2<\/td><\/tr><tr><td>0005H<\/td><td>90 12 34<\/td><td>MOV DPTR,#1234H<\/td><td>2<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">2 + 3 + 3 = <b>8 byte<\/b> · 1 + 2 + 2 = <b>5 chu kỳ máy<\/b> × 1 µs<\/p><p class=\"mt-calc\">So sánh 8086: MOV AX,1234h → B8H 34H 12H (byte thấp trước)<\/p>", "say": "<p>Ở 8051 kiểu gốc, 1 chu kỳ máy = 12 chu kỳ dao động; thạch anh 12 MHz cho 1 µs mỗi chu kỳ máy. Chip 8051 đời mới có thể nhanh hơn: đọc datasheet của đúng chip.<\/p>"}]}, {"label": "Lỗi: Viết FFH thay vì 0FFH", "note": "Thông báo lỗi chép từ lần chạy thật của sdas8051 và NASM.", "steps": [{"t": "Dòng nguồn MOV A,#FFH", "html": "<p class=\"mt-calc\">MOV A,#<b>F<\/b>FH<\/p>", "say": "<p>Trình dịch đọc toán hạng từ trái sang. Ký tự đầu là chữ F, nên FFH được coi là một tên (nhãn, hằng EQU…), không phải số.<\/p>"}, {"t": "Trình dịch báo ký hiệu chưa định nghĩa", "html": "<p class=\"mt-calc\">err8051.s:5: Error: <u> undefined symbol encountered during assembly<\/p><p class=\"mt-calc\">err8086.asm:10: error: symbol `FFh' not defined<\/p>", "say": "<p>Hai thông báo trên chép từ lần chạy thật của sdas8051 (dòng tương đương <code>mov a,#ffh<\/code>) và NASM (dòng 8086 <code>mov al, FFh<\/code>). Bài chưa chạy dòng này trên Keil A51 nên chưa chép thông báo của Keil; câu chữ của mỗi trình dịch khác nhau.<\/p>"}, {"t": "Sửa: MOV A,#0FFH → 74H FFH", "html": "<p class=\"mt-calc\">MOV A,#<b>0<\/b>FFH → 74H 0FFH<\/p>", "ask": {"q": "Cách sửa nào đúng?", "o": ["MOV A,#0FFH", "MOV A,#FF", "MOV A,#FFh"], "a": 0}, "say": "<p>Số 0 đứng đầu không đổi giá trị nhưng cho trình dịch biết đây là số.<\/p>"}]}, {"label": "Bẫy: Quên dấu # trong MOV A,#30H", "note": "Lệnh vẫn dịch được nhưng đọc ô nhớ thay vì nạp hằng số.", "steps": [{"t": "Giả định: ô RAM trong 30H đang chứa 7EH", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ô RAM<\/th><th scope=\"col\">Nội dung (giả định)<\/th><\/tr><\/thead><tbody><tr><td>2FH<\/td><td>00H<\/td><\/tr><tr><td>30H<\/td><td class=\"new\">7EH<\/td><\/tr><tr><td>31H<\/td><td>00H<\/td><\/tr><\/tbody><\/table>", "say": "<p>Nội dung các ô trong bảng là giả định cho ví dụ, không phải giá trị sau reset: RAM trong không có giá trị xác định sau khi cấp nguồn.<\/p>"}, {"t": "Đúng: MOV A,#30H → 74H 30H, A = 30H", "html": "<p class=\"mt-calc\">MOV A,<b>#<\/b>30H → 74H 30H · A = <b>30H<\/b><\/p>"}, {"t": "Thiếu #: MOV A,30H → E5H 30H", "html": "<p class=\"mt-calc\">MOV A,30H → <b>0E5H 30H<\/b><\/p>", "ask": {"q": "Sau MOV A,30H, thanh ghi A bằng bao nhiêu?", "o": ["30H", "7EH (byte đang ở ô 30H)", "Trình dịch báo lỗi, không chạy"], "a": 1}}, {"t": "A = 7EH: chạy được nhưng sai giá trị", "html": "<p class=\"mt-calc\">A = <b>7EH<\/b> (đọc từ ô 30H)<\/p>", "say": "<p>Cả hai lệnh đều hợp lệ nên trình dịch không báo lỗi. Đọc mã máy là cách phát hiện nhanh: 74H là nạp hằng, E5H là đọc ô nhớ trực tiếp.<\/p>"}]}, {"label": "Cảnh báo: Hằng số không vừa 8 bit", "note": "MOV A,#300 bị cắt còn 2CH mà không có thông báo.", "steps": [{"t": "MOV A,#300: hằng số này cần mấy bit?", "html": "<p class=\"mt-calc\">MOV A,#300 · thanh ghi A có 8 bit (0…255)<\/p>", "say": "<p>Trước khi dịch, tự hỏi: hằng số có vừa chỗ nhận không?<\/p>"}, {"t": "300 = 256 + 44 = 12CH: cần 9 bit", "html": "<p class=\"mt-calc\">300 = 256 + 44 = 12CH = 1 0010 1100B<\/p>", "ask": {"q": "300 viết ở hệ 16 là gì?", "o": ["300H", "1C2H", "12CH"], "a": 2}}, {"t": "Thanh ghi A chỉ có 8 bit", "html": "<div class=\"nt-byte\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bit<\/th><th scope=\"col\">7<\/th><th scope=\"col\">6<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số<\/td><td>128<\/td><td>64<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Giá trị<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td class=\"hi\">1<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><p class=\"mt-calc\">bit 8 (trọng số 256) không có chỗ → còn 0010 1100B = 2CH = 44<\/p>", "say": "<p>Một byte chỉ chứa 0…255. Phần vượt quá bị mất nếu trình dịch cắt bớt.<\/p>"}, {"t": "sdas8051 không báo lỗi, sinh 74H 2CH", "html": "<p class=\"mt-calc\">mov a,#300 → 74 2C (A = 44, không phải 300)<\/p>", "say": "<p>Trình dịch dùng để kiểm chứng bài (sdas8051, SDCC 4.2.0) lặng lẽ giữ 8 bit thấp. Trình dịch khác có thể báo lỗi. Đừng dựa vào trình dịch: tự kiểm tra hằng 8 bit nằm trong 0…255.<\/p>"}]}, {"label": "Bẫy: #10, #10H và #10B khác nhau", "note": "Không hậu tố là thập phân.", "steps": [{"t": "Ba dòng trông gần giống nhau", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dòng A51<\/th><th scope=\"col\">Mã máy<\/th><th scope=\"col\">A (hệ 10)<\/th><\/tr><\/thead><tbody><tr><td>MOV A,#10<\/td><td>?<\/td><td>?<\/td><\/tr><tr><td>MOV A,#10H<\/td><td>?<\/td><td>?<\/td><\/tr><tr><td>MOV A,#10B<\/td><td>?<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Không hậu tố là thập phân: 10 = 0AH", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dòng A51<\/th><th scope=\"col\">Mã máy<\/th><th scope=\"col\">A (hệ 10)<\/th><\/tr><\/thead><tbody><tr><td>MOV A,#10<\/td><td class=\"new\">74H 0AH<\/td><td class=\"new\">10<\/td><\/tr><tr><td>MOV A,#10H<\/td><td>?<\/td><td>?<\/td><\/tr><tr><td>MOV A,#10B<\/td><td>?<\/td><td>?<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "MOV A,#10 nạp giá trị nào vào A?", "o": ["0AH (mười)", "10H (mười sáu)", "02H (hai)"], "a": 0}}, {"t": "10H = 16, 10B = 2", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dòng A51<\/th><th scope=\"col\">Mã máy<\/th><th scope=\"col\">A (hệ 10)<\/th><\/tr><\/thead><tbody><tr><td>MOV A,#10<\/td><td>74H 0AH<\/td><td>10<\/td><\/tr><tr><td>MOV A,#10H<\/td><td>74H 10H<\/td><td class=\"new\">16<\/td><\/tr><tr><td>MOV A,#10B<\/td><td>74H 02H<\/td><td class=\"new\">2<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mã máy chép từ sdas8051. Thói quen an toàn: luôn ghi hậu tố H cho hex và B cho nhị phân, kể cả khi số trông như thập phân.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l1"),"l1",[{"kind": "base", "t": "Đọc giá trị một byte", "d": "<p>Đổi mỗi giá trị sang hệ được yêu cầu. Hex có thể viết A5, A5H, 0A5H hoặc 0xA5 (chữ hoa hay thường đều được); nhị phân viết đủ 8 bit hoặc bỏ số 0 bên trái đều được, có thể thêm hậu tố B.<\/p>", "items": [{"q": "01101100B ở hệ 10", "f": "dec", "a": 108}, {"q": "01101100B ở hệ 16", "f": "hex", "a": 108}, {"q": "0C8H ở hệ 10", "f": "dec", "a": 200}, {"q": "200 ở hệ 2", "f": "bin", "a": 200}, {"q": "255 ở hệ 16", "f": "hex", "a": 255}, {"q": "Giá trị không dấu lớn nhất của một word 16 bit, ở hệ 10", "f": "dec", "a": 65535}], "hints": ["Một byte là 2 chữ số hex; mỗi chữ số hex là 4 bit, nhóm từ bên phải.", "Giá trị một byte = 16 × (nibble cao) + (nibble thấp). Trong 0C8H, chữ số C bằng 12.", "200 = 12 × 16 + 8 → C8H → 1100 1000. Một word có 16 bit: lớn nhất là 2¹⁶ − 1."], "why": "0110 1100B = 64 + 32 + 8 + 4 = 108 = 6CH; 0C8H = 12 × 16 + 8 = 200 = 1100 1000B; 255 = FFH (viết trong A51 là 0FFH); 2¹⁶ − 1 = 65 535."}, {"kind": "base", "t": "Byte điều khiển phần cứng 8051", "d": "<p>Dùng 8051 kiểu gốc, thạch anh 12 MHz (1 chu kỳ máy = 12 chu kỳ dao động = 1 µs). LED trên P\u0031 nối theo giả định của bài: sáng khi chân ở mức 0. Trả lời theo hệ ghi sau mỗi câu.<\/p>", "items": [{"q": "Sau MOV P\u0031,#11110000B, giá trị P\u0031", "f": "hex", "a": 240}, {"q": "P\u0031 = 0E7H: số LED đang sáng", "f": "dec", "a": 2}, {"q": "MOV PSW,#10H chọn băng thanh ghi số", "f": "dec", "a": 2}, {"q": "Khi đó R0 nằm ở ô RAM trong có địa chỉ", "f": "hex", "a": 16}, {"q": "Byte thứ hai (sau opcode 90H) của MOV DPTR,#1234H", "f": "hex", "a": 18}, {"q": "Đoạn MOV A,#3CH / MOV P\u0031,#0A5H / MOV DPTR,#1234H dài bao nhiêu byte", "f": "dec", "a": 8}, {"q": "Đoạn đó chạy hết bao nhiêu µs", "f": "dec", "a": 5}], "hints": ["Viết byte ra đủ 8 bit trước; chân P\u0031.k ứng với bit k. LED sáng khi bit bằng 0.", "PSW: RS1 là bit 4, RS0 là bit 3; băng n bắt đầu ở ô 8 × n. MOV DPTR của 8051 đặt byte cao trước.", "MOV A,#data: 2 byte, 1 chu kỳ máy. MOV direct,#data và MOV DPTR,#data16: 3 byte, 2 chu kỳ máy."], "why": "1111 0000B = F0H; 0E7H = 1110 0111B có 2 bit 0 → 2 LED sáng; 10H = 0001 0000B → RS1 = 1, RS0 = 0 → băng 2, R0 ở ô 2 × 8 = 16 = 10H; 90H 12H 34H nên byte thứ hai là 12H; 2 + 3 + 3 = 8 byte; 1 + 2 + 2 = 5 chu kỳ máy = 5 µs."}, {"kind": "opt", "t": "Ghi một byte ra bốn chỗ: ít byte, ít chu kỳ", "d": "<p>8051 kiểu gốc, thạch anh 12 MHz (1 chu kỳ máy = 1 µs), đoạn mã chạy ngay sau reset (A = 00H, PSW = 00H, P\u0031 = P\u0032 = FFH; RAM trong chưa xác định). Viết đoạn mã Keil A51 để khi chạy xong: <b>A = 0A5H<\/b>, <b>P\u0031 = 0A5H<\/b>, <b>P\u0032 = 0A5H<\/b>, <b>R0 của băng thanh ghi 2<\/b> (ô RAM trong 10H) bằng 0A5H, và băng đang chọn vẫn là <b>băng 0<\/b>. Giới hạn: <b>tối đa 8 byte và 4 chu kỳ máy<\/b>.<\/p><p>Code mẫu cho kết quả đúng nhưng dài 16 byte, chạy 10 chu kỳ máy. Trang dịch đoạn mã, chạy rồi so từng yêu cầu và giới hạn; bảng Listing ghi mã máy, số chu kỳ của từng lệnh. Được dùng MOV, CLR, CPL, INC, DEC, NOP với A, R0…R7, #hằng, địa chỉ trực tiếp (00H…7FH, P\u0030…P\u0033, PSW, ACC, B, SP, DPL, DPH); hằng viết theo Keil A51 (0A5H, không viết A5H hay 0xA5).<\/p>", "init": null, "want": [{"k": "A", "v": 165, "t": "A"}, {"k": "P\u0031", "v": 165, "t": "P\u0031"}, {"k": "P\u0032", "v": 165, "t": "P\u0032"}, {"k": "RAM10", "v": 165, "t": "Ô RAM 10H (R0 của băng 2)"}, {"k": "RS", "v": 0, "t": "Băng thanh ghi đang chọn"}], "limit": {"bytes": 8, "cycles": 4}, "hints": ["Tra bảng: MOV A,#data 2 byte, 1 chu kỳ máy; MOV direct,#data 3 byte, 2 chu kỳ máy; MOV direct,A chỉ 2 byte, 1 chu kỳ máy. Nạp hằng một lần vào A rồi chép A ra.", "R0 của băng 2 chính là ô RAM trong 10H (băng n bắt đầu ở ô 8 × n). Ghi thẳng vào địa chỉ 10H thì không phải đổi PSW hai lần.", "Bốn lệnh: MOV A,#0A5H rồi MOV đích,A với đích lần lượt là P\u0031, P\u0032 và 10H."], "why": "MOV A,#0A5H = 74H A5H (2 byte, 1 chu kỳ máy); mỗi MOV direct,A = F5H + địa chỉ (2 byte, 1 chu kỳ máy): P\u0031 = 90H, P\u0032 = A0H, R0 của băng 2 = ô 10H. Tổng 2 + 2 + 2 + 2 = 8 byte, 1 + 1 + 1 + 1 = 4 chu kỳ máy = 4 µs. Code mẫu: 2 + 3 + 3 + 3 + 2 + 3 = 16 byte, 1 + 2 + 2 + 2 + 1 + 2 = 10 chu kỳ máy. Viết R0 thì phải đổi băng rồi đổi lại (thêm 6 byte, 4 chu kỳ máy); địa chỉ trực tiếp 10H đi thẳng tới ô đó. Mã máy và số chu kỳ đã chạy trên sdas8051 và ucsim s51.", "sample": "        MOV     A,#0A5H                 ; A = 0A5H\n        MOV     P\u0031,#0A5H                ; P\u0031 = 0A5H\n        MOV     P\u0032,#0A5H                ; P\u0032 = 0A5H\n        MOV     PSW,#10H                ; chọn băng 2\n        MOV     R0,#0A5H                ; R0 của băng 2 = ô 10H\n        MOV     PSW,#00H                ; về băng 0"}]);

makeQuiz("quiz1","score1",[{"q": "Byte 1001 0110B viết ở hệ 16 và hệ 10 là gì?", "o": ["69H = 105", "96H = 96", "96H = 144", "96H = 150"], "a": 3, "e": "1001 = 9, 0110 = 6 nên byte là 96H = 9 × 16 + 6 = 150. 69H là đảo hai nibble; “96” là đọc chữ số hex như số thập phân; 144 là quên cộng nibble thấp."}, {"q": "Trong Keil A51, dòng nào nạp số 255 vào thanh ghi A?", "o": ["MOV A,#FFH", "MOV A,#0FFH", "MOV A,0FFH", "MOV A,#255H"], "a": 1, "e": "FFH bắt đầu bằng chữ cái nên bị hiểu là tên ký hiệu; thiếu # thì 0FFH là địa chỉ trực tiếp, không phải hằng số; 255H = 597, không vừa 8 bit."}, {"q": "Sau MOV PSW,#10H, thanh ghi R0 của băng đang dùng nằm ở ô RAM trong nào?", "o": ["08H", "00H", "10H", "18H"], "a": 2, "e": "10H = 0001 0000B: RS1 (bit 4) = 1, RS0 (bit 3) = 0 nên dùng băng 2, bắt đầu ở ô 2 × 8 = 16 = 10H. Đáp án 08H là nhầm bit 4 thành RS0."}, {"q": "Bộ nhớ chương trình 8051 chứa 3 byte 90H 12H 34H, là lệnh MOV DPTR,#data16. DPTR nhận giá trị nào?", "o": ["3412H", "9012H", "1234H", "1290H"], "a": 2, "e": "90H là opcode; lệnh này của 8051 đặt byte cao (12H) trước byte thấp (34H). 3412H là áp nhầm quy ước byte thấp trước của 8086 (MOV AX,1234h = B8H 34H 12H)."}, {"q": "Một ô nhớ chứa 35H. Bit 4 của ô nhớ đó bằng bao nhiêu?", "o": ["1", "0", "3, vì nibble cao là 3", "Chưa biết nếu chưa rõ số có dấu"], "a": 0, "e": "35H = 0011 0101B; bit 4 là bit thấp nhất của nibble cao, bằng 1. Đáp án 0 là đếm vị trí từ bên trái. Giá trị từng bit không phụ thuộc cách diễn giải có dấu hay không dấu."}]);

